import * as T from './vendor/three.module.js';
import {packActor,restoreActor} from './actor-state.js';
import {statusStep,canSense} from './combat-rules.js';
import {steer} from './navigation.js';
export function ghostModel(parent){const g=new T.Group();parent.add(g);const cloth=new T.MeshStandardMaterial({color:0xb5d7dc,emissive:0x315d6b,emissiveIntensity:.6,transparent:true,opacity:.65,roughness:.8,depthWrite:false});function mesh(geo,x,y,z,mat=cloth){const m=new T.Mesh(geo,mat);m.position.set(x,y,z);g.add(m);return m}mesh(new T.ConeGeometry(.43,1.4,10,1,true),0,.68,0);mesh(new T.SphereGeometry(.29,12,10),0,1.53,0);for(const side of [-1,1]){const arm=mesh(new T.CapsuleGeometry(.08,.45,3,6),side*.4,1.05,.06);arm.rotation.z=side*.45;mesh(new T.SphereGeometry(.045,8,6),side*.10,1.57,.25,new T.MeshBasicMaterial({color:0xf1ffff}))}const aura=mesh(new T.TorusGeometry(.58,.018,5,32),0,.22,0,new T.MeshBasicMaterial({color:0xc2f1ff,transparent:true,opacity:.4}));aura.rotation.x=Math.PI/2;g.userData.aura=aura;return g}
export function chapelGhost({root,camera,blocked,rand=Math.random}){const g=ghostModel(root);g.visible=false;const n={g,id:'chapel-ghost',species:'ghost',name:'Подчинённый звонарь',hp:110,maxHp:110,home:new T.Vector3(1000,.6,-87),target:new T.Vector3(1000,.6,-87),heading:0,cooldown:1.5,aggro:null,generation:0,hit:false};let spawned=false,defeated=false,time=0,fear=0,fearReady=8,casting=0,castFear=false;const shots=[];
 function clear(){for(const b of shots){b.m.removeFromParent();b.m.geometry.dispose();b.m.material.dispose()}shots.length=0;fear=0;casting=0;n.aggro=null}
 function spawn(){if(spawned)return false;spawned=true;defeated=false;n.hp=n.maxHp;n.g.visible=true;n.g.position.copy(n.home);n.hit=false;n.root=n.stun=n.slow=n.bleedLeft=n.markLeft=0;n.cooldown=1.5;fearReady=8;return true}
 function sight(){const from=n.g.position.clone().add(new T.Vector3(0,1.2,0));for(let t=.02;t<1;t+=.02)if(blocked(from.clone().lerp(camera.position,t)))return false;return true}
 function fire(data){const m=new T.Mesh(new T.SphereGeometry(.16,10,8),new T.MeshBasicMaterial({color:0xf4ffff}));m.position.fromArray(data.position);root.add(m);shots.push({...data,m,v:new T.Vector3().fromArray(data.velocity)})}
 function killed(){if(!spawned||defeated)return false;defeated=true;n.hp=0;g.visible=false;clear();return true}
 function tick(dt,{onDamage,onSound=()=>{}}){fear=Math.max(0,fear-dt);if(!spawned||defeated)return;time+=dt;const step=statusStep(n,dt);n.cooldown=Math.max(0,n.cooldown-step);fearReady=Math.max(0,fearReady-step);const d=Math.hypot(camera.position.x-g.position.x,camera.position.z-g.position.z);const sensed=canSense(n,camera,d,32);if(!n.aggro&&sensed)n.aggro=camera.position.clone();g.position.y=.65+Math.sin(time*2)*.18;g.userData.aura.rotation.z=time;n.heading=Math.atan2(camera.position.x-g.position.x,camera.position.z-g.position.z);g.rotation.y=n.heading;
  if(step>0&&casting>0){casting=Math.max(0,casting-step);g.userData.aura.scale.setScalar(1+(castFear?.7:.25)*Math.sin((1-casting/.65)*Math.PI));if(casting===0&&sight()){if(castFear&&d<23){fear=3;onSound('ice')}else if(!castFear){const pos=g.position.clone().add(new T.Vector3(0,1.2,0));fire({position:pos.toArray(),velocity:camera.position.clone().sub(pos).normalize().multiplyScalar(24).toArray(),age:0})}}}else if(step>0&&n.aggro){const desired=new T.Vector3(T.MathUtils.clamp(camera.position.x+Math.sin(time)*1.3,998.4,1001.6),g.position.y,T.MathUtils.clamp(camera.position.z+(d<6?-5:3),-99,-85));steer(n,desired,2.1,step,(x,z)=>x>998.2&&x<1001.8&&z>-100&&z<-84&&!blocked(new T.Vector3(x,1.5,z)));if(n.cooldown===0&&d<32&&sight()){castFear=fearReady===0&&d<23;casting=.65;n.cooldown=castFear?2.3:1.7;if(castFear)fearReady=12}}
  for(let i=shots.length-1;i>=0;i--){const b=shots[i],old=b.m.position.clone();b.age+=dt;b.m.position.addScaledVector(b.v,dt);let wall=false,hit=false;const count=Math.max(1,Math.ceil(old.distanceTo(b.m.position)/.12));for(let j=1;j<=count;j++){const p=old.clone().lerp(b.m.position,j/count);if(blocked(p)){wall=true;break}if(p.distanceTo(camera.position)<.5){hit=true;break}}if(hit)onDamage(12,'magic','ghost');if(hit||wall||b.age>4){b.m.removeFromParent();b.m.geometry.dispose();b.m.material.dispose();shots.splice(i,1)}}
 }
 return {n,spawn,killed,tick,clear,get spawned(){return spawned},get defeated(){return defeated},get fear(){return fear},snapshot:()=>({spawned,defeated,time,fear,fearReady,casting,castFear,actor:packActor(n),shots:shots.map(b=>({position:b.m.position.toArray(),velocity:b.v.toArray(),age:b.age}))}),restore(s){clear();spawned=!!s?.spawned;defeated=!!s?.defeated;time=s?.time||0;fear=s?.fear||0;fearReady=s?.fearReady??8;casting=s?.casting||0;castFear=!!s?.castFear;if(s?.actor)restoreActor(n,s.actor);else{n.hp=110;n.g.position.copy(n.home);n.hit=false;n.root=n.stun=n.slow=n.bleedLeft=n.markLeft=0}g.visible=spawned&&!defeated;for(const b of s?.shots||[])fire(b)}};
}
